package com.banktabstorage;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.UnaryOperator;

final class StorageLayout
{
    private static final int MAX_ENTRIES = 1000;
    private final List<StoredStorageEntry> entries;

    StorageLayout(List<StoredStorageEntry> source)
    {
        if (source == null || source.size() > MAX_ENTRIES)
        {
            throw new IllegalArgumentException("The saved folder organization is too large");
        }
        Map<String, StoredStorageEntry> byId = new LinkedHashMap<>();
        for (StoredStorageEntry entry : source)
        {
            if (entry == null)
            {
                throw new IllegalArgumentException("The saved folder organization contains an invalid entry");
            }
            StoredStorageEntry copy = entry.validatedCopy();
            if (byId.putIfAbsent(copy.getId(), copy) != null)
            {
                throw new IllegalArgumentException("The saved folder organization contains duplicate entries");
            }
        }
        for (StoredStorageEntry entry : byId.values())
        {
            Set<String> visited = new HashSet<>();
            visited.add(entry.getId());
            String parentId = entry.getParentId();
            while (parentId != null)
            {
                StoredStorageEntry parent = byId.get(parentId);
                if (parent == null || !parent.isFolder() || !visited.add(parentId) || visited.size() > 32)
                {
                    throw new IllegalArgumentException("The saved folder organization contains an invalid parent");
                }
                parentId = parent.getParentId();
            }
        }
        entries = List.copyOf(byId.values());
    }

    static StorageLayout empty()
    {
        return new StorageLayout(List.of());
    }

    List<StoredStorageEntry> getEntries()
    {
        return entries;
    }

    StoredStorageEntry find(String id)
    {
        for (StoredStorageEntry entry : entries)
        {
            if (entry.getId().equals(id))
            {
                return entry;
            }
        }
        throw new IllegalArgumentException("The selected tab or folder no longer exists");
    }

    List<StoredStorageEntry> children(String parentId)
    {
        List<StoredStorageEntry> result = new ArrayList<>();
        for (StoredStorageEntry entry : entries)
        {
            if (Objects.equals(parentId, entry.getParentId()))
            {
                result.add(entry);
            }
        }
        return result;
    }

    StorageLayout reconcile(List<StoredBankTag> tabs)
    {
        Set<String> remaining = new HashSet<>();
        for (StoredBankTag tab : tabs)
        {
            remaining.add(tab.getName());
        }
        List<StoredStorageEntry> result = new ArrayList<>();
        for (StoredStorageEntry entry : entries)
        {
            if (entry.isFolder() || remaining.remove(entry.getName()))
            {
                result.add(entry);
            }
        }
        for (StoredBankTag tab : tabs)
        {
            if (remaining.remove(tab.getName()))
            {
                result.add(StoredStorageEntry.tab(tab.getName()));
            }
        }
        return new StorageLayout(result);
    }

    StorageLayout addFolder(StoredStorageEntry folder)
    {
        List<StoredStorageEntry> result = new ArrayList<>(entries);
        result.add(folder);
        return new StorageLayout(result);
    }

    StorageLayout updateFolder(String id, UnaryOperator<StoredStorageEntry> update)
    {
        if (!find(id).isFolder())
        {
            throw new IllegalArgumentException("Select a folder first");
        }
        List<StoredStorageEntry> result = new ArrayList<>();
        for (StoredStorageEntry entry : entries)
        {
            result.add(entry.getId().equals(id) ? update.apply(entry) : entry);
        }
        return new StorageLayout(result);
    }

    boolean canMove(String id, String parentId)
    {
        try
        {
            find(id);
            String ancestor = parentId;
            while (ancestor != null)
            {
                if (id.equals(ancestor))
                {
                    return false;
                }
                StoredStorageEntry parent = find(ancestor);
                if (!parent.isFolder())
                {
                    return false;
                }
                ancestor = parent.getParentId();
            }
            return true;
        }
        catch (IllegalArgumentException exception)
        {
            return false;
        }
    }

    StorageLayout move(String id, String parentId, int index)
    {
        if (!canMove(id, parentId))
        {
            throw new IllegalArgumentException("A folder cannot be moved into itself or one of its children");
        }
        StoredStorageEntry moving = find(id);
        List<StoredStorageEntry> siblings = children(parentId);
        int target = index < 0 ? siblings.size() : Math.min(index, siblings.size());
        int previous = siblings.indexOf(moving);
        if (previous >= 0 && previous < target)
        {
            target--;
        }
        siblings.remove(moving);
        List<StoredStorageEntry> result = new ArrayList<>(entries);
        result.remove(moving);
        int insertion = target < siblings.size() ? result.indexOf(siblings.get(target))
            : siblings.isEmpty() ? result.size() : result.indexOf(siblings.get(siblings.size() - 1)) + 1;
        result.add(insertion, moving.withParent(parentId));
        return new StorageLayout(result);
    }

    StorageLayout removeFolder(String id)
    {
        StoredStorageEntry folder = find(id);
        if (!folder.isFolder())
        {
            throw new IllegalArgumentException("Select a folder first");
        }
        List<StoredStorageEntry> contents = children(id);
        List<StoredStorageEntry> result = new ArrayList<>();
        for (StoredStorageEntry entry : entries)
        {
            if (entry.getId().equals(id))
            {
                for (StoredStorageEntry child : contents)
                {
                    result.add(child.withParent(folder.getParentId()));
                }
            }
            else if (!id.equals(entry.getParentId()))
            {
                result.add(entry);
            }
        }
        return new StorageLayout(result);
    }

    StorageLayout merge(StorageLayout incoming, List<StoredBankTag> tabs, boolean replace)
    {
        if (replace)
        {
            return incoming.reconcile(tabs);
        }
        Map<String, StoredStorageEntry> result = new LinkedHashMap<>();
        for (StoredStorageEntry entry : entries)
        {
            result.put(entry.getId(), entry);
        }
        for (StoredStorageEntry entry : incoming.entries)
        {
            result.putIfAbsent(entry.getId(), entry);
        }
        return new StorageLayout(new ArrayList<>(result.values())).reconcile(tabs);
    }
}

package com.banktabstorage;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import net.runelite.client.util.Text;

final class StoredBankTag
{
    private static final int MAX_NAME_LENGTH = 80;
    private static final int MAX_ITEMS = 10000;
    private static final int MAX_LAYOUT_SIZE = 10000;
    private String name;
    private int iconItemId;
    private List<Integer> itemIds;
    private List<Integer> layout;
    private boolean hidden;
    private boolean enabled;

    private StoredBankTag()
    {
    }

    StoredBankTag(String name, int iconItemId, List<Integer> itemIds, List<Integer> layout,
        boolean hidden, boolean enabled)
    {
        this.name = name;
        this.iconItemId = iconItemId;
        this.itemIds = itemIds;
        this.layout = layout;
        this.hidden = hidden;
        this.enabled = enabled;
    }

    StoredBankTag validatedCopy()
    {
        String normalizedName = normalizeName(name);
        if (iconItemId < 0)
        {
            throw new IllegalArgumentException("A saved tab has an invalid icon item ID");
        }
        List<Integer> normalizedItems = normalizeItems(itemIds);
        List<Integer> normalizedLayout = normalizeLayout(layout);
        return new StoredBankTag(normalizedName, iconItemId, normalizedItems, normalizedLayout, hidden, enabled);
    }

    StoredBankTag withEnabled(boolean newEnabled)
    {
        return new StoredBankTag(name, iconItemId, itemIds, layout, hidden, newEnabled).validatedCopy();
    }

    StoredBankTag copy()
    {
        return new StoredBankTag(name, iconItemId, itemIds, layout, hidden, enabled).validatedCopy();
    }

    String getName()
    {
        return name;
    }

    int getIconItemId()
    {
        return iconItemId;
    }

    List<Integer> getItemIds()
    {
        return new ArrayList<>(itemIds);
    }

    List<Integer> getLayout()
    {
        return layout == null ? null : new ArrayList<>(layout);
    }

    boolean hasLayout()
    {
        return layout != null;
    }

    boolean isHidden()
    {
        return hidden;
    }

    boolean isEnabled()
    {
        return enabled;
    }

    int getItemCount()
    {
        return itemIds.size();
    }

    static String normalizeName(String value)
    {
        if (value == null)
        {
            throw new IllegalArgumentException("A saved tab is missing its name");
        }
        StringBuilder filtered = new StringBuilder();
        value.codePoints().filter(StoredBankTag::isAllowedNameCharacter).forEach(filtered::appendCodePoint);
        String normalized = Text.standardize(filtered.toString());
        if (normalized.isEmpty() || normalized.length() > MAX_NAME_LENGTH)
        {
            throw new IllegalArgumentException("A saved tab has an invalid name");
        }
        return normalized;
    }

    private static boolean isAllowedNameCharacter(int value)
    {
        return "</>:".indexOf(value) == -1;
    }

    private static List<Integer> normalizeItems(List<Integer> values)
    {
        if (values == null || values.size() > MAX_ITEMS)
        {
            throw new IllegalArgumentException("A saved tab has an invalid item list");
        }
        Set<Integer> unique = new LinkedHashSet<>();
        for (Integer value : values)
        {
            if (value == null || value == Integer.MIN_VALUE)
            {
                throw new IllegalArgumentException("A saved tab has an invalid item ID");
            }
            unique.add(value);
        }
        List<Integer> normalized = new ArrayList<>(unique);
        Collections.sort(normalized);
        return normalized;
    }

    private static List<Integer> normalizeLayout(List<Integer> values)
    {
        if (values == null)
        {
            return null;
        }
        if (values.size() > MAX_LAYOUT_SIZE)
        {
            throw new IllegalArgumentException("A saved tab has an invalid layout");
        }
        List<Integer> normalized = new ArrayList<>(values.size());
        for (Integer value : values)
        {
            if (value == null || value < -1)
            {
                throw new IllegalArgumentException("A saved tab has an invalid layout item ID");
            }
            normalized.add(value);
        }
        return normalized;
    }

    @Override
    public boolean equals(Object other)
    {
        if (this == other)
        {
            return true;
        }
        if (!(other instanceof StoredBankTag))
        {
            return false;
        }
        StoredBankTag tab = (StoredBankTag) other;
        return iconItemId == tab.iconItemId
            && hidden == tab.hidden
            && enabled == tab.enabled
            && Objects.equals(name, tab.name)
            && Objects.equals(itemIds, tab.itemIds)
            && Objects.equals(layout, tab.layout);
    }

    @Override
    public int hashCode()
    {
        return Objects.hash(name, iconItemId, itemIds, layout, hidden, enabled);
    }
}

package com.banktabstorage;

import java.util.UUID;

final class StoredStorageEntry
{
    private String id;
    private String name;
    private String parentId;
    private boolean folder;
    private int iconItemId;
    private boolean expanded;

    private StoredStorageEntry()
    {
    }

    private StoredStorageEntry(String id, String name, String parentId, boolean folder,
        int iconItemId, boolean expanded)
    {
        this.id = id;
        this.name = name;
        this.parentId = parentId;
        this.folder = folder;
        this.iconItemId = iconItemId;
        this.expanded = expanded;
    }

    static StoredStorageEntry tab(String name)
    {
        String normalized = StoredBankTag.normalizeName(name);
        return new StoredStorageEntry("tab:" + normalized, normalized, null, false, -1, false);
    }

    static StoredStorageEntry folder(String name, String parentId)
    {
        return new StoredStorageEntry("folder:" + UUID.randomUUID(), name, parentId, true, -1, true)
            .validatedCopy();
    }

    StoredStorageEntry validatedCopy()
    {
        if (id == null || id.length() > 160 || name == null || name.trim().isEmpty()
            || name.length() > 80 || name.codePoints().anyMatch(Character::isISOControl)
            || iconItemId < -1 || (parentId != null && parentId.length() > 160))
        {
            throw new IllegalArgumentException("The saved folder organization contains an invalid entry");
        }
        if (folder)
        {
            if (!id.startsWith("folder:") || id.length() <= 7)
            {
                throw new IllegalArgumentException("A saved folder has an invalid identifier");
            }
        }
        else if (!id.equals("tab:" + StoredBankTag.normalizeName(name)))
        {
            throw new IllegalArgumentException("A saved tab has an invalid organization identifier");
        }
        return new StoredStorageEntry(id, folder ? name.trim() : StoredBankTag.normalizeName(name),
            parentId, folder, iconItemId, expanded);
    }

    StoredStorageEntry withParent(String parent)
    {
        return new StoredStorageEntry(id, name, parent, folder, iconItemId, expanded).validatedCopy();
    }

    StoredStorageEntry withName(String value)
    {
        return new StoredStorageEntry(id, value, parentId, folder, iconItemId, expanded).validatedCopy();
    }

    StoredStorageEntry withIcon(int value)
    {
        return new StoredStorageEntry(id, name, parentId, folder, value, expanded).validatedCopy();
    }

    StoredStorageEntry withExpanded(boolean value)
    {
        return new StoredStorageEntry(id, name, parentId, folder, iconItemId, value).validatedCopy();
    }

    String getId()
    {
        return id;
    }

    String getName()
    {
        return name;
    }

    String getParentId()
    {
        return parentId;
    }

    boolean isFolder()
    {
        return folder;
    }

    int getIconItemId()
    {
        return iconItemId;
    }

    boolean isExpanded()
    {
        return expanded;
    }

    @Override
    public String toString()
    {
        return name;
    }
}

package com.banktabstorage;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

final class StoredTabCollection
{
    private StoredTabCollection()
    {
    }

    static List<StoredBankTag> merge(List<StoredBankTag> existing, List<StoredBankTag> incoming, boolean replace)
    {
        Map<String, StoredBankTag> merged = new LinkedHashMap<>();
        if (!replace)
        {
            for (StoredBankTag tab : existing)
            {
                StoredBankTag copy = tab.validatedCopy();
                merged.put(copy.getName(), copy);
            }
        }
        for (StoredBankTag tab : incoming)
        {
            StoredBankTag copy = tab.validatedCopy();
            merged.put(copy.getName(), copy);
        }
        return new ArrayList<>(merged.values());
    }

    static List<StoredBankTag> syncEnabled(List<StoredBankTag> tabs, List<String> visibleNames)
    {
        Set<String> visible = new LinkedHashSet<>();
        for (String name : visibleNames)
        {
            visible.add(StoredBankTag.normalizeName(name));
        }
        List<StoredBankTag> result = new ArrayList<>(tabs.size());
        for (StoredBankTag tab : tabs)
        {
            result.add(tab.withEnabled(visible.contains(tab.getName())));
        }
        return result;
    }

    static List<StoredBankTag> setEnabled(List<StoredBankTag> tabs, String name, boolean enabled)
    {
        String normalized = StoredBankTag.normalizeName(name);
        List<StoredBankTag> result = new ArrayList<>(tabs.size());
        for (StoredBankTag tab : tabs)
        {
            result.add(tab.getName().equals(normalized) ? tab.withEnabled(enabled) : tab.copy());
        }
        return result;
    }

    static List<StoredBankTag> remove(List<StoredBankTag> tabs, String name)
    {
        String normalized = StoredBankTag.normalizeName(name);
        List<StoredBankTag> result = new ArrayList<>();
        for (StoredBankTag tab : tabs)
        {
            if (!tab.getName().equals(normalized))
            {
                result.add(tab.copy());
            }
        }
        return result;
    }

    static StoredBankTag find(List<StoredBankTag> tabs, String name)
    {
        String normalized = StoredBankTag.normalizeName(name);
        for (StoredBankTag tab : tabs)
        {
            if (tab.getName().equals(normalized))
            {
                return tab.copy();
            }
        }
        return null;
    }
}

package com.banktabstorage;

import com.google.gson.Gson;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class BankTabStorageCodecTest
{
    private final BankTabStorageCodec codec = new BankTabStorageCodec(new Gson());

    @Test
    public void roundTripsCompleteSnapshots()
    {
        StoredBankTag source = new StoredBankTag("Slayer", 4151, List.of(4151, -11840),
            List.of(4151, -1, 11840), true, true);
        List<StoredBankTag> decoded = codec.decode(codec.encode(List.of(source)));
        Assert.assertEquals(List.of(source.validatedCopy()), decoded);
    }

    @Test
    public void importsRuneLiteSingleTabFormat()
    {
        List<StoredBankTag> decoded = codec.decode("banktags,1,slayer,4151,4151,layout,2,11840");
        Assert.assertEquals(1, decoded.size());
        StoredBankTag tab = decoded.get(0);
        Assert.assertEquals("slayer", tab.getName());
        Assert.assertEquals(4151, tab.getIconItemId());
        Assert.assertEquals(List.of(4151, 11840), tab.getItemIds());
        Assert.assertEquals(List.of(-1, -1, 11840), tab.getLayout());
        Assert.assertFalse(tab.isEnabled());
    }

    @Test
    public void importsLegacyStorageFormat()
    {
        Assert.assertTrue(codec.decode("{\"kind\":\"bank-tags-storage\",\"version\":1,\"tabs\":[]}").isEmpty());
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsUnknownJson()
    {
        codec.decode("{\"kind\":\"something-else\",\"version\":1,\"tabs\":[]}");
    }
}

